  // opting itself into the fields only it may declare.
  const roots = activePacks.map((p) => ({ id: p.id, dir: join(p.dir, 'tasks') }));
  const builtIn = builtInTasksRoot(root);
  if (builtIn) roots.push({ id: BUILT_IN_PACK, dir: builtIn });

  const found = [];
  for (const pack of roots) {
    if (!existsSync(pack.dir)) continue;
    let names;
    try {
      names = readdirSync(pack.dir, { withFileTypes: true })
        .filter((d) => d.isDirectory()).map((d) => d.name).sort();
    } catch (e) {
      errors.push({ pack: pack.id, what: `${pack.id}'s tasks/ is not a readable directory: ${e.message}`, fix: `make ${relative(root, pack.dir)} a directory (or remove it)` });
      continue;
    }
    for (const name of names) {
      const taskDir = join(pack.dir, name);
      const file = findTaskDeclaration(taskDir);
      if (file === null) continue;
      found.push({ pack: pack.id, name, taskDir, file });
    }
  }
  return { found, errors };
}

